import React, { useEffect, useState } from "react";
import { useParams } from "react-router-dom";

const VideoPage = () => {
  const { id } = useParams(); // id da rota
  const [videos, setVideos] = useState([]);
  const [selected, setSelected] = useState(null);

  useEffect(() => {
    fetch("http://localhost:5000/api/videos")
      .then((response) => response.json())
      .then((data) => {
        setVideos(data.videos || []);
        const current = data.videos?.[id - 1]; // exemplo: usa o índice como id
        if (current) {
          setSelected(
            `http://192.168.1.4/UniversidadeNutrihouse/DOMANA/CDP/${current}`
          );
        }
      })
      .catch((err) => console.error("Erro ao buscar vídeos:", err));
  }, [id]);

  if (!selected) {
    return (
      <div className="min-h-screen flex items-center justify-center text-xl">
        Carregando vídeo...
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col items-center p-6">
      {/* Título */}
      <h1 className="text-3xl font-semibold text-center mb-8">
        {`Curso ${id}`}
      </h1>

      <div className="flex w-full max-w-6xl bg-white rounded-lg shadow-lg overflow-hidden">
        {/* Módulos */}
        <div className="w-1/4 bg-red-600 text-white p-6">
          <h2 className="text-xl font-semibold mb-6">MÓDULOS</h2>
          <ul>
            {videos.map((videoName, index) => (
              <li
                key={index}
                className="flex items-center mb-4 cursor-pointer"
                onClick={() =>
                  setSelected(
                    `http://192.168.1.4/UniversidadeNutrihouse/DOMANA/CDP/${videoName}`
                  )
                }
              >
                <span className="mr-2">✔️</span>
                <span>{videoName}</span>
              </li>
            ))}
          </ul>
          <button className="mt-6 w-full bg-white text-red-600 font-semibold py-2 px-4 rounded-lg shadow hover:bg-gray-100 transition">
            Material de Apoio
          </button>
        </div>

        {/* Player de Vídeo */}
        <div className="w-3/4 p-6 flex flex-col">
          <div className="relative mb-6">
            <video className="w-full h-96 rounded-lg shadow" controls autoPlay>
              <source src={selected} type="video/mp4" />
              Seu navegador não suporta vídeo.
            </video>
          </div>

          <div className="p-4 bg-gray-100 rounded-lg">
            <p className="text-lg font-medium">
              {selected.split("/").pop().replace(".mp4", "")}
            </p>
            <p className="text-sm text-gray-500">Duração: --</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default VideoPage;
